create or replace function public.business_benchmark_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with peers as(select b.id,count(ci.id)::numeric check_ins from businesses b left join locations l on l.business_id=b.id left join check_ins ci on ci.location_id=l.id and ci.checked_in_at between p_start and p_end group by b.id),ranked as(select id,check_ins,percent_rank() over(order by check_ins) percentile from peers),mine as(select * from ranked where id=p_business_id) select jsonb_build_object('business_check_ins',coalesce((select check_ins from mine),0),'peer_businesses',(select count(*) from peers),'peer_average_check_ins',coalesce(round((select avg(check_ins) from peers)::numeric,2),0),'percentile',coalesce(round((100*(select percentile from mine))::numeric,2),0)); $$;
